sp_widget.client_script:
function ($rootScope, $scope, spUtil) {
  var c = this;

	// Update local array, then let server persist
c.snNoteUpdate = function(name, sysID) {
  for (var i = 0; i < c.data.notes.length; i++) {
    if (c.data.notes[i].sys_id == name.data.sys_id) {
      if (name.data.record.note) {
        c.data.notes[i].note = name.data.record.note.display_value;
      }
      if (name.data.record.title) {
        c.data.notes[i].title = name.data.record.title.display_value;
      }
      // Let the server know we changed data (lightweight ping)
      c.server.update();
      break;
    }
  }
};

// Delete on server and replace local array with fresh data
c.snNoteDelete = function(sysID) {
  c.server.get({
    action: 'snDeleteNote',
    noteID: sysID
  }).then(function(r) {
    c.data.notes = r.data.notes; // replace with updated list from server
  });
};


  // Click handler: tell Body to load this note
  c.selectItem = function (idx) {
    if (!c.data || !c.data.notes || !c.data.notes[idx]) return;

    var id = String(c.data.notes[idx].sys_id || '');
    $rootScope.noteID = id;
    $rootScope.$emit('selectNote', id);
  };

	// Create a new note, add it to the list, and select it
c.newNote = function () {
  // Optionally you can send seed values via input if you want
  c.server.get({ action: 'newNote' }).then(function (r) {
    if (!r || !r.data || !r.data.noteID) return;

    var created = {
      sys_id: r.data.noteID,
      title:  (r.data.newNote && r.data.newNote.title) || '',
      note:   (r.data.newNote && r.data.newNote.note)  || ''
    };

    // Put new note at the top of the list
    c.data.notes = c.data.notes || [];
    c.data.notes.unshift(created);

    // Select it so the Body loads it for editing
    $rootScope.noteID = created.sys_id;
    $rootScope.$emit('selectNote', created.sys_id);

    // Ensure UI refresh
    $scope.$applyAsync();
  });
};

// Live update: when Body saves a change, update the row in-place (keep 20-char preview)
$rootScope.$on('noteUpdated', function (event, payload) {
  if (!payload || !payload.noteID) return;
  if (!c.data || !Array.isArray(c.data.notes)) return;

  for (var i = 0; i < c.data.notes.length; i++) {
    var n = c.data.notes[i];
    if (n.sys_id === payload.noteID) {
      n.title = payload.title || '';
      var full = payload.body || '';
      n.note = full.substring(0, 20); // keep consistent with server preview
      break;
    }
  }
  $scope.$applyAsync();
});


  // Live delete: remove the row from the list immediately
  $rootScope.$on('noteDeleted', function (event, payload) {
    if (!payload || !payload.noteID) return;
    if (!c.data || !Array.isArray(c.data.notes)) return;

    c.data.notes = c.data.notes.filter(function (n) {
      return n.sys_id !== payload.noteID;
    });
    $scope.$applyAsync();
  });


spUtil.recordWatch($scope, "x_snc_createnotes_note", "numberISNOTEMPTY", function (name) {
  // Debug
  console.log(name?.data?.operation);
  console.log(name);

  // Guard: must have operation + sys_id
  if (!name || !name.data || !name.data.operation || !name.data.sys_id) return;

  // Normalize: sometimes record might be missing on delete
  var rec = name.data.record || {};

  if (name.data.operation === "update") {
    // Add a quick log to see incoming fields
    console.log('update payload fields:', Object.keys(rec));
    c.snNoteUpdate(name, name.data.sys_id);
  }

  if (name.data.operation === "delete") {
    c.snNoteDelete(name.data.sys_id);
  }

  if (name.data.operation === "insert") {
    c.server.refresh();
  }
});


}

sp_widget.script:
(function() {

  data.notes = [];

  // Build the list for the current user
  var noteGR = new GlideRecord('x_snc_createnotes_note');
  noteGR.addQuery('user', gs.getUser().getID());
  noteGR.orderByDesc('sys_created_on');
	noteGR.setLimit(options.maximum_records_to_display);
  noteGR.query();
  while (noteGR.next()) {
    var noteObj = {};
    $sp.getRecordDisplayValues(noteObj, noteGR, 'number,title,sys_id');
    noteObj.note = noteGR.getValue('note').slice(0, 20);
    data.notes.push(noteObj);
  }

  // Handle actions
  if (input) {

		if (input.action == 'snDeleteNote') {
  var delNote = new GlideRecord('x_snc_createnotes_note');
  // The record may already be deleted; this is just a safeguard
  if (delNote.get(input.noteID)) {
    delNote.deleteRecord();
  }
  // Return the refreshed list
  var list = [];
  var gr = new GlideRecord('x_snc_createnotes_note');
  gr.orderBy('number');
  gr.query();
  while (gr.next()) {
    list.push({
      sys_id: gr.getUniqueValue(),
      number: gr.getDisplayValue('number'),
      title: gr.getValue('title') + '',
      note: gr.getValue('note') + ''
    });
  }
  data.notes = list;
}


    if (input.action === 'newNote') {
      var newNote = new GlideRecord('x_snc_createnotes_note');
      newNote.initialize();
      newNote.setValue('user', gs.getUserID());  // <-- important so it appears in this user's list
      newNote.setValue('title', input.title || '');
      newNote.setValue('note', input.body  || '');
      var id = newNote.insert();

      // return the newly created record back to the client
      data.noteID = id;
      data.newNote = {};
      $sp.getRecordValues(data.newNote, newNote, 'title,note,sys_id');
    }
  }
})();
